mapper.select:
select id, user_email, stat_date, keyboard_count, mouse_click_count, mouse_distance,
       scroll_distance, total_duration, created_at, updated_at
from daily_statistics
where user_email = #{user_email}
  and stat_date = #{stat_date}

select id, user_email, stat_date, app_name, total_duration, sessions,
       last_window_title, created_at, updated_at
from app_usage_records
where user_email = #{user_email}
  and stat_date = #{stat_date}
  and app_name = #{app_name}

select id, user_email, stat_date, app_name, total_duration, sessions,
       last_window_title, created_at, updated_at
from app_usage_records
where user_email = #{user_email}
  and stat_date = #{stat_date}
order by total_duration desc, id asc

select id, record_id, window_title, created_at from app_window_titles where record_id in
#{record_id}
order by id asc

select id, user_email, stat_date, last_active_app, created_at
from data_date_index
where user_email = #{user_email}
  and stat_date = #{stat_date}

mapper.update:
update data_date_index
set last_active_app = #{last_active_app}
where user_email = #{user_email}
  and stat_date = #{stat_date}

mapper.select:
select id, user_email, stat_date, last_active_app, created_at
from data_date_index
where user_email = #{user_email}
  and stat_date >= #{start_date}
  and stat_date <= #{end_date}
order by stat_date asc
